-- ----------------------------
-- Table structure for design_form
-- ----------------------------
DROP TABLE IF EXISTS `design_form`;
CREATE TABLE `design_form` (
  `id` varchar(50) NOT NULL COMMENT 'ID',
  `desform_code` varchar(200) NOT NULL COMMENT '表单编码',
  `desform_name` varchar(200) DEFAULT NULL COMMENT '表单名称',
  `desform_icon` varchar(50) DEFAULT NULL COMMENT '表单图标',
  `desform_design_json` longtext COMMENT '表单设计JSON',
  `cgform_code` varchar(32) DEFAULT NULL COMMENT '绑定的CgformCode',
  `parent_id` varchar(32) DEFAULT NULL COMMENT '父表单id',
  `parent_code` varchar(200) DEFAULT NULL COMMENT '父表单code',
  `desform_type` tinyint(1) DEFAULT '1' COMMENT '表单类型，1=主表，2=子表',
  `iz_oa_show` tinyint(1) DEFAULT NULL,
  `iz_mobile_view` tinyint(1) DEFAULT NULL COMMENT '是否是移动视图（1=是，0或null=否），一个 desform 只能有一个移动视图',
  `create_by` varchar(32) DEFAULT NULL COMMENT '创建人',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(32) DEFAULT NULL COMMENT '修改人',
  `update_time` datetime DEFAULT NULL COMMENT '修改时间',
  `tenant_id` int DEFAULT '0' COMMENT '租户ID',
  `low_app_id` varchar(50) DEFAULT NULL COMMENT '应用ID',
  `update_count` int DEFAULT NULL COMMENT '乐观锁版本',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE KEY `uniq_desform_code` (`desform_code`) USING BTREE,
  KEY `idx_desform_cgform_code` (`cgform_code`) USING BTREE,
  KEY `idx_desform_type` (`desform_type`) USING BTREE,
  KEY `idx_desform_lowapp_id` (`low_app_id`) USING BTREE,
  KEY `idx_desform_tenant_id` (`tenant_id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3;

-- ----------------------------
-- Records of design_form
-- ----------------------------
BEGIN;
COMMIT;

-- ----------------------------
-- Table structure for design_form_auth
-- ----------------------------
DROP TABLE IF EXISTS `design_form_auth`;
CREATE TABLE `design_form_auth` (
  `id` varchar(32) NOT NULL COMMENT '主键ID',
  `desform_id` varchar(32) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL COMMENT '表单设计ID',
  `desform_code` varchar(200) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL COMMENT '表单设计编码',
  `permission_type` varchar(100) NOT NULL COMMENT '权限类型（data、button、field）',
  `auth_com_key` varchar(100) DEFAULT NULL COMMENT '组件id json中的key',
  `auth_title` varchar(100) DEFAULT NULL COMMENT '权限名称',
  `auth_field` varchar(100) DEFAULT NULL COMMENT '权限字段',
  `auth_type` varchar(50) DEFAULT NULL COMMENT '授权类型（字段权限时存储可见1或可编辑2；数据权限存储查询类型（大于、小于、等于等规则）；按钮权限此项为空）',
  `auth_value` varchar(200) DEFAULT NULL COMMENT '授权规则值',
  `auth_value_type` varchar(50) DEFAULT NULL COMMENT '授权规则值类型',
  `auth_scope_is_all` varchar(10) DEFAULT 'Y' COMMENT '授权范围【Y 所有人 ,N 不是所有人】默认所有人',
  `auth_scope_users_val` varchar(200) DEFAULT NULL COMMENT '授权范围值，保存user登录账户',
  `auth_scope_roles_val` varchar(200) DEFAULT NULL COMMENT '授权范围值，保存授权角色编码',
  `auth_scope_departs_val` varchar(200) DEFAULT NULL COMMENT '授权范围值，保存部门编码',
  `sub_table` tinyint(1) DEFAULT NULL COMMENT '是否是子表内权限，1=true，0=false',
  `sub_title` varchar(100) DEFAULT NULL COMMENT '子表的标题',
  `sub_key` varchar(100) DEFAULT NULL COMMENT '子表的Key',
  `status` tinyint(1) DEFAULT NULL COMMENT '状态（0=无效，1=有效）1',
  `create_by` varchar(32) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '创建人',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(32) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '修改人',
  `update_time` datetime DEFAULT NULL COMMENT '修改时间',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `idx_desfmauth_desform_id` (`desform_id`) USING BTREE,
  KEY `idx_desfmauth_desform_code` (`desform_code`) USING BTREE,
  KEY `idx_desfmauth_permission_type` (`permission_type`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='表单设计器权限表，字段级权限';

-- ----------------------------
-- Records of design_form_auth
-- ----------------------------
BEGIN;
COMMIT;

-- ----------------------------
-- Table structure for design_form_commuse
-- ----------------------------
DROP TABLE IF EXISTS `design_form_commuse`;
CREATE TABLE `design_form_commuse` (
  `id` varchar(32) NOT NULL,
  `user_id` varchar(32) DEFAULT NULL COMMENT '用户id',
  `desform_id` varchar(32) DEFAULT NULL,
  `create_by` varchar(32) DEFAULT NULL COMMENT '创建人',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(32) DEFAULT NULL COMMENT '修改人',
  `update_time` datetime DEFAULT NULL COMMENT '修改时间',
  `form_type` varchar(50) DEFAULT NULL COMMENT '表单类型-online/design',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3 COMMENT='常用流程表';

-- ----------------------------
-- Records of design_form_commuse
-- ----------------------------
BEGIN;
COMMIT;

-- ----------------------------
-- Table structure for design_form_data
-- ----------------------------
DROP TABLE IF EXISTS `design_form_data`;
CREATE TABLE `design_form_data` (
  `id` varchar(32) NOT NULL COMMENT 'ID',
  `desform_id` varchar(32) NOT NULL COMMENT '表单设计ID',
  `desform_code` varchar(200) NOT NULL COMMENT '表单设计编码',
  `desform_name` varchar(200) DEFAULT NULL COMMENT '表单设计名称',
  `desform_data_json` longtext COMMENT '表单数据JSON',
  `online_form_code` varchar(200) DEFAULT NULL COMMENT 'Online表单的Code',
  `online_form_data_id` varchar(32) DEFAULT NULL COMMENT 'Online数据表中的id，用于同步修改',
  `bpm_status` varchar(2) DEFAULT NULL COMMENT '流程状态',
  `create_by` varchar(32) DEFAULT NULL COMMENT '创建人',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(32) DEFAULT NULL COMMENT '修改人',
  `update_time` datetime DEFAULT NULL COMMENT '修改时间',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `idx_dfd_desform_id` (`desform_id`) USING BTREE,
  KEY `idx_dfd_desform_code` (`desform_code`) USING BTREE,
  KEY `idx_dfd_online_form_code` (`online_form_code`) USING BTREE,
  KEY `idx_dfd_online_form_data_id` (`online_form_data_id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3;

