-- ----------------------------
-- Table structure for design_form_route
-- ----------------------------
DROP TABLE IF EXISTS `design_form_route`;
CREATE TABLE `design_form_route` (
  `id` varchar(32) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL COMMENT 'ID',
  `desform_id` varchar(32) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL COMMENT '表单设计ID',
  `desform_code` varchar(200) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL COMMENT '表单设计编码',
  `route_name` varchar(200) DEFAULT NULL COMMENT '路由名称',
  `route_type` varchar(2) DEFAULT NULL COMMENT '路由跳转类型（1=表单跳转；2=菜单跳转；3=外部跳转）',
  `route_path` varchar(200) DEFAULT NULL COMMENT '下一步路由地址（表单跳转时填表单的code；菜单跳转填菜单路径；外部跳转填全链接）',
  `status` tinyint(1) DEFAULT NULL COMMENT '状态（0=无效，1=有效）',
  `create_by` varchar(32) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '创建人',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(32) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '修改人',
  `update_time` datetime DEFAULT NULL COMMENT '修改时间',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `idx_dfr_desform_id` (`desform_id`) USING BTREE,
  KEY `idx_dfr_desform_code` (`desform_code`) USING BTREE,
  KEY `idx_dfr_status` (`status`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

-- ----------------------------
-- Records of design_form_route
-- ----------------------------
BEGIN;
COMMIT;

