CREATE TABLE `design_form_url_auth` (
  `id` varchar(32) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL,
  `desform_id` varchar(32) NOT NULL COMMENT '表单ID',
