-- ----------------------------
-- Table structure for eoa_file
-- ----------------------------
DROP TABLE IF EXISTS `eoa_file`;
CREATE TABLE `eoa_file` (
  `id` varchar(36) NOT NULL COMMENT 'id',
  `parent_id` varchar(32) DEFAULT NULL COMMENT '父ID',
  `is_folder` varchar(2) DEFAULT NULL COMMENT '是否文件夹 1：是  0：否',
  `title` varchar(100) DEFAULT NULL COMMENT '名称',
  `doc_type` varchar(100) DEFAULT NULL COMMENT '文档类型（folder:文件夹 excel:excel doc:word pp:ppt image:图片  archive:其他文档 video:视频）',
  `doc_extension` varchar(20) DEFAULT NULL COMMENT '文件后缀',
  `key_words` varchar(255) DEFAULT NULL COMMENT '关键字',
  `doc_size` double(13,2) DEFAULT NULL COMMENT '文件大小（kb）',
  `owner_name` varchar(64) DEFAULT NULL COMMENT '文档作者',
  `doc_url` varchar(255) DEFAULT NULL COMMENT '文件路径',
  `description` varchar(255) DEFAULT NULL COMMENT '描述',
  `read_count` int unsigned DEFAULT '0' COMMENT '阅读次数',
  `down_count` int unsigned DEFAULT '0' COMMENT '下载次数',
  `auth_role_ids` varchar(2000) DEFAULT NULL COMMENT '授权角色id',
  `auth_user_ids` varchar(2000) DEFAULT NULL COMMENT '授权用户id',
  `auth_depart_ids` varchar(2000) DEFAULT NULL COMMENT '授权组织机构ID',
  `post_code` varchar(500) DEFAULT NULL COMMENT '文件编号',
  `create_by` varchar(100) DEFAULT NULL COMMENT '创建人',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(100) DEFAULT NULL COMMENT '更新人',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `sys_org_code` varchar(50) DEFAULT NULL COMMENT '组织机构编码',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3 COMMENT='文档内容表';

-- ----------------------------
-- Records of eoa_file
-- ----------------------------
BEGIN;
COMMIT;

-- ----------------------------
-- Table structure for eoa_file_log
-- ----------------------------
DROP TABLE IF EXISTS `eoa_file_log`;
CREATE TABLE `eoa_file_log` (
  `id` varchar(32) NOT NULL COMMENT '文档日志id',
  `doc_id` varchar(32) DEFAULT NULL COMMENT '文档id',
  `user_id` varchar(32) DEFAULT NULL COMMENT '操作人',
  `operate_type` varchar(2) DEFAULT NULL COMMENT '类型（1：创建、2：编辑  3：删除 4：查看 5：下载）',
  `user_ip` varchar(32) DEFAULT NULL COMMENT '客户端IP',
  `operate_time` datetime DEFAULT NULL COMMENT '操作时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3 COMMENT='文档日志表';

-- ----------------------------
-- Records of eoa_file_log
-- ----------------------------
BEGIN;
COMMIT;

-- ----------------------------
-- Table structure for eoa_plan
-- ----------------------------
DROP TABLE IF EXISTS `eoa_plan`;
CREATE TABLE `eoa_plan` (
  `id` varchar(32) NOT NULL,
  `title` varchar(255) NOT NULL COMMENT '标题',
  `start_time` datetime DEFAULT NULL COMMENT '开始时间',
  `end_time` datetime DEFAULT NULL COMMENT '结束时间',
  `type` varchar(2) DEFAULT NULL COMMENT '类型：1日常记录  2本周工作  3下周计划',
  `all_day` varchar(2) DEFAULT NULL COMMENT '是否全天  0否  1是',
  `urgent_level` varchar(2) DEFAULT NULL COMMENT '紧急程度 1一般 2重要 3紧急',
  `receiver_ids` varchar(1000) DEFAULT NULL COMMENT '接收人ids',
  `remind_type` varchar(255) DEFAULT NULL COMMENT '提醒类型 1邮件 2短信 3系统消息 ',
  `remark` text COMMENT '备注/内容',
  `status` varchar(2) DEFAULT '0' COMMENT '状态 0未开始 1进行中 2已完成',
  `create_by` varchar(50) DEFAULT NULL COMMENT '创建人',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(50) DEFAULT NULL COMMENT '修改人',
  `update_time` datetime DEFAULT NULL COMMENT '修改时间',
  `sys_org_code` varchar(50) DEFAULT NULL COMMENT '组织机构编码',
  `plan_color` varchar(10) DEFAULT NULL COMMENT '颜色',
  `remind` varchar(2) DEFAULT NULL COMMENT '提醒（0 不提醒，1 开始时，2 提前5分钟，3 提前10分钟，4 提前15分钟，5 提前30分钟，6 提前1小时，7 提前2小时）',
  `reminders` varchar(2) DEFAULT NULL COMMENT '重复提醒（0 不重复，1 每天，2 每周，3 每月（当日），4 每年（当日））',
  `reminder_time` datetime DEFAULT NULL COMMENT '提醒时间',
  `join_person` text COMMENT '参与人员',
  `tenant_id` int DEFAULT NULL COMMENT '租户id',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3 COMMENT='日程任务';

-- ----------------------------
-- Records of eoa_plan
-- ----------------------------
BEGIN;
COMMIT;

-- ----------------------------
-- Table structure for ext_act_bpm_file
-- ----------------------------
DROP TABLE IF EXISTS `ext_act_bpm_file`;
CREATE TABLE `ext_act_bpm_file` (
  `id` varchar(32) NOT NULL,
  `bpm_log_id` varchar(32) NOT NULL COMMENT '审批日志id',
  `base_path` varchar(255) DEFAULT NULL COMMENT '根目录',
  `file_path` varchar(1000) DEFAULT NULL COMMENT '文件路径',
  `file_name` varchar(1000) DEFAULT NULL COMMENT '文件名称',
  `file_size` varchar(20) DEFAULT NULL COMMENT '文件大小',
  `create_by` varchar(255) DEFAULT NULL COMMENT '创建人',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(255) DEFAULT NULL COMMENT '更新人',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `idx_eabf_bpm_log_id` (`bpm_log_id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3 COMMENT='审批日志文件';

-- ----------------------------
-- Records of ext_act_bpm_file
-- ----------------------------
BEGIN;
COMMIT;

-- ----------------------------
-- Table structure for ext_act_bpm_log
-- ----------------------------
DROP TABLE IF EXISTS `ext_act_bpm_log`;
CREATE TABLE `ext_act_bpm_log` (
  `id` varchar(64) NOT NULL,
  `business_key` varchar(64) DEFAULT NULL COMMENT '业务流程key',
  `proc_inst_id` varchar(64) NOT NULL COMMENT '流程实例id',
  `proc_name` varchar(255) DEFAULT NULL COMMENT '流程名称',
  `task_id` varchar(64) DEFAULT NULL COMMENT '任务id',
  `task_def_key` varchar(100) DEFAULT NULL COMMENT '任务key',
  `task_name` varchar(255) DEFAULT NULL COMMENT '任务名称',
  `op_user_id` varchar(100) DEFAULT NULL COMMENT '操作人ID',
  `op_user_name` varchar(100) DEFAULT NULL COMMENT '操作人名称',
  `op_time` datetime DEFAULT NULL COMMENT '操作时间',
  `op_type` varchar(100) DEFAULT NULL COMMENT '操作类型:1普通任务;2会签任务;3驳回;4作废;5取回',
  `op_status` varchar(64) DEFAULT NULL COMMENT '操作状态（自行结合业务定义）',
  `remarks` varchar(4000) DEFAULT NULL COMMENT '意见',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3 COMMENT='流程审批日志';

-- ----------------------------
-- Records of ext_act_bpm_log
-- ----------------------------
BEGIN;
COMMIT;

-- ----------------------------
-- Table structure for ext_act_design_flow_data
-- ----------------------------
DROP TABLE IF EXISTS `ext_act_design_flow_data`;
CREATE TABLE `ext_act_design_flow_data` (
  `id` varchar(32) NOT NULL,
  `desform_id` varchar(32) NOT NULL COMMENT '表单ID',
  `desform_code` varchar(200) DEFAULT NULL COMMENT '表单Code',
  `desform_name` varchar(255) DEFAULT NULL COMMENT '表单名称',
  `desform_data_id` varchar(32) DEFAULT NULL COMMENT '表单数据ID',
  `bpm_title` varchar(200) DEFAULT NULL COMMENT '流程标题',
  `title_exp` varchar(255) DEFAULT NULL COMMENT '业务标题表达式',
  `process_name` varchar(200) DEFAULT NULL COMMENT '流程名称',
  `flow_code` varchar(200) DEFAULT NULL COMMENT '流程编码',
  `table_name` varchar(200) DEFAULT NULL COMMENT '存储主表名，一对多只存主表',
  `bpm_status` varchar(50) DEFAULT NULL COMMENT '流程状态',
  `create_by` varchar(32) DEFAULT NULL COMMENT '创建人',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(32) DEFAULT NULL COMMENT '修改人',
  `update_time` datetime DEFAULT NULL COMMENT '修改时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3;

-- ----------------------------
-- Records of ext_act_design_flow_data
-- ----------------------------
BEGIN;
COMMIT;

-- ----------------------------
-- Table structure for ext_act_expression
-- ----------------------------
DROP TABLE IF EXISTS `ext_act_expression`;
CREATE TABLE `ext_act_expression` (
  `id` varchar(32) NOT NULL COMMENT 'id',
  `name` varchar(255) DEFAULT NULL COMMENT '表达式名称',
  `expression` varchar(255) DEFAULT NULL COMMENT '表达式',
  `create_by` varchar(50) DEFAULT NULL COMMENT '创建人登录名称',
  `create_time` datetime DEFAULT NULL COMMENT '创建日期',
  `update_by` varchar(50) DEFAULT NULL COMMENT '更新人登录名称',
  `update_time` datetime DEFAULT NULL COMMENT '更新日期',
  `low_app_id` varchar(32) DEFAULT NULL COMMENT '应用ID',
  `tenant_id` int DEFAULT NULL COMMENT '租户ID',
  `biz_type` varchar(20) DEFAULT NULL COMMENT '表达式业务类型 candidateUser:指定人表达式 candidateUsers:候选人表达式 other 其他)',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3 COMMENT='流程表达式';

-- ----------------------------
-- Records of ext_act_expression
-- ----------------------------
BEGIN;
COMMIT;

-- ----------------------------
-- Table structure for ext_act_flow_data
-- ----------------------------
DROP TABLE IF EXISTS `ext_act_flow_data`;
CREATE TABLE `ext_act_flow_data` (
  `id` varchar(32) NOT NULL COMMENT '序号',
  `form_data_id` varchar(32) DEFAULT NULL COMMENT '多流程表单id',
  `process_key` varchar(100) DEFAULT NULL COMMENT '流程key',
  `process_name` varchar(200) DEFAULT NULL COMMENT '流程名称',
  `process_exp_title` varchar(255) DEFAULT NULL COMMENT '流程业务标题(表达式值)',
  `process_inst_id` varchar(64) DEFAULT NULL COMMENT '流程实例ID',
  `bpm_status_field` varchar(200) DEFAULT NULL COMMENT '多流程状态列名',
  `bpm_status` varchar(50) DEFAULT NULL COMMENT '流程状态1:待提交;2:处理中;3处理完毕;4流程作废;5流程挂起',
  `form_table_name` varchar(50) DEFAULT NULL COMMENT '多流程表单表名',
  `form_type` varchar(10) DEFAULT NULL COMMENT '表单类型：1Online表单,2自定义表单,3自定义开发',
  `relation_code` varchar(50) DEFAULT NULL COMMENT '多流程表单编码',
  `user_id` varchar(200) DEFAULT NULL COMMENT '流程发起人',
  `process_form_id` varchar(36) DEFAULT NULL COMMENT '业务关联配置id',
  `create_by` varchar(50) DEFAULT NULL COMMENT '创建人登录名称',
  `create_time` datetime DEFAULT NULL COMMENT '创建日期',
  `update_by` varchar(50) DEFAULT NULL COMMENT '更新人登录名称',
  `update_time` datetime DEFAULT NULL COMMENT '更新日期',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE KEY `uniq_codeformid` (`relation_code`,`form_data_id`,`process_inst_id`) USING BTREE,
  UNIQUE KEY `uniq_proceskey_formid` (`form_data_id`,`process_key`,`process_inst_id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3 COMMENT='流程表单业务表';

-- ----------------------------
-- Records of ext_act_flow_data
-- ----------------------------
BEGIN;
COMMIT;

-- ----------------------------
-- Table structure for ext_act_listener
-- ----------------------------
DROP TABLE IF EXISTS `ext_act_listener`;
CREATE TABLE `ext_act_listener` (
  `id` varchar(32) NOT NULL,
  `listener_name` varchar(50) DEFAULT NULL COMMENT '监听器名称',
  `listener_type` smallint DEFAULT NULL COMMENT '监听类型 1执行监听 2任务监听',
  `listener_event` varchar(20) DEFAULT NULL COMMENT 'Event属性 触发监听器的事件类型\ncreate：在任务被创建，且所有的任务属性被设置后发生。 \nassignment：在任务分配给某人后发生。注意：当流程执行到 userTask，在触发 create 事件之前，首先触\n发 assignment 事件。这像是一个反常的顺序，但原因很实际：接收到 create 事件，我们往往会要查看包括\n代理人在内的所有任务的属性。 \ncomplete：在任务完成后，任务从运行时的数据中被删除之前发生。',
  `listener_value_type` varchar(20) DEFAULT NULL COMMENT '值类型  javaClass JAVA类，expression 表达式',
  `listener_value` varchar(100) DEFAULT NULL COMMENT '监听器表达式或类名',
  `listener_status` smallint DEFAULT NULL COMMENT '监听器状态\n1：启用\n2：禁用',
  `del_flag` varchar(10) NOT NULL DEFAULT '0' COMMENT '删除状态（0，正常，1已删除）',
  `create_by` varchar(32) DEFAULT NULL COMMENT '创建人',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(32) DEFAULT NULL COMMENT '修改人',
  `update_time` datetime DEFAULT NULL COMMENT '修改时间',
  `low_app_id` varchar(32) DEFAULT NULL COMMENT '应用ID',
  `tenant_id` int DEFAULT NULL COMMENT '租户ID',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3;

-- ----------------------------
-- Records of ext_act_listener
-- ----------------------------
BEGIN;
COMMIT;

-- ----------------------------
-- Table structure for ext_act_mutil_flow_data
-- ----------------------------
DROP TABLE IF EXISTS `ext_act_mutil_flow_data`;
CREATE TABLE `ext_act_mutil_flow_data` (
  `id` varchar(32) NOT NULL COMMENT '序号',
  `form_data_id` varchar(32) DEFAULT NULL COMMENT '多流程表单id',
  `process_key` varchar(300) DEFAULT NULL COMMENT '流程key',
  `process_inst_id` varchar(64) DEFAULT NULL COMMENT '流程实例ID',
  `bpm_status_field` varchar(200) DEFAULT NULL,
  `bpm_status` varchar(50) DEFAULT NULL COMMENT '多流程状态列名',
  `form_table_name` varchar(50) DEFAULT NULL COMMENT '多流程表单表名',
  `relation_code` varchar(32) DEFAULT NULL COMMENT '多流程表单编码',
  `create_by` varchar(50) DEFAULT NULL COMMENT '创建人登录名称',
  `create_time` datetime DEFAULT NULL COMMENT '创建日期',
  `update_by` varchar(50) DEFAULT NULL COMMENT '更新人登录名称',
  `update_time` datetime DEFAULT NULL COMMENT '更新日期',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE KEY `uniq_codeformid` (`relation_code`,`form_data_id`) USING BTREE,
  UNIQUE KEY `uk_eamfd_codeformid` (`relation_code`,`form_data_id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3 COMMENT='多流程表单业务表';

-- ----------------------------
-- Records of ext_act_mutil_flow_data
-- ----------------------------
BEGIN;
COMMIT;

-- ----------------------------
-- Table structure for ext_act_process
-- ----------------------------
DROP TABLE IF EXISTS `ext_act_process`;
CREATE TABLE `ext_act_process` (
  `id` varchar(50) NOT NULL,
  `process_type` varchar(32) DEFAULT NULL COMMENT '流程类型',
  `process_key` varchar(100) DEFAULT NULL COMMENT '流程ID',
  `process_name` varchar(50) DEFAULT NULL COMMENT '流程名称',
  `process_status` smallint DEFAULT NULL COMMENT '流程状态0未发布;1已发布',
  `process_deploy_time` datetime DEFAULT NULL COMMENT '流程发布时间',
  `process_xml_path` varchar(100) DEFAULT NULL COMMENT '流程XML路径',
  `process_json` longtext,
  `low_app_id` varchar(50) DEFAULT NULL COMMENT '应用ID',
  `process_xml` longblob COMMENT '流程内容',
  `note` varchar(200) DEFAULT NULL COMMENT '备注',
  `pc_icon` varchar(50) DEFAULT NULL COMMENT '表单图标(PC)',
  `app_icon` varchar(50) DEFAULT NULL COMMENT '表单图标(APP)',
  `create_by` varchar(32) DEFAULT NULL COMMENT '创建人id',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_time` datetime DEFAULT NULL COMMENT '修改时间',
  `update_by` varchar(32) DEFAULT NULL COMMENT '修改人id',
  `urge_status` varchar(3) DEFAULT '1' COMMENT '是否允许催办1是0否',
  `back_status` varchar(3) DEFAULT '1' COMMENT '是否允许取回流程1是0否',
  `graphic_status` varchar(3) DEFAULT '1' COMMENT '是否允许查看流程图1是0否',
  `auto_submit_status` varchar(3) DEFAULT '0' COMMENT '是否启用自动提交流程1是0否',
  `notify_way` varchar(100) DEFAULT NULL COMMENT '通知类型(多个会以逗号隔开)',
  `tenant_id` int DEFAULT NULL COMMENT '租户ID',
  `update_count` int DEFAULT NULL COMMENT 'mp乐观锁字段',
  `start_type` varchar(30) DEFAULT NULL COMMENT '流程开始节点类型  applyEvent、 tableEvent、timerEvent、userEvent、subEvent、buttonEvent',
  `open_status` smallint DEFAULT '1' COMMENT '流程关闭状态 0 关闭1 开启（默认开启）',
  `run_concurrent_mode` varchar(1) DEFAULT NULL COMMENT '并发运行方式 并行(默认）0、串行 1',
  `trigger_other_process` varchar(1) DEFAULT NULL COMMENT '是否允许触发其他流程 0否  1允许',
  `error_notice_user_ids` varchar(1000) DEFAULT NULL COMMENT '流程异常通知人员，多个逗号分割',
  `error_notice_repeat` varchar(300) DEFAULT NULL COMMENT '流程异常通知频率',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `idx_epros_process_type` (`process_type`) USING BTREE,
  KEY `idx_epros_process_key` (`process_key`) USING BTREE,
  KEY `idx_epros_low_app_id` (`low_app_id`) USING BTREE,
  KEY `idx_epros_tenant_id` (`tenant_id`) USING BTREE,
  KEY `idx_epros_process_name` (`process_name`) USING BTREE,
  KEY `idx_epros_openstatus` (`open_status`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3 COMMENT='流程设计表';

-- ----------------------------
-- Records of ext_act_process
-- ----------------------------
BEGIN;
COMMIT;

-- ----------------------------
-- Table structure for ext_act_process_form
-- ----------------------------
DROP TABLE IF EXISTS `ext_act_process_form`;
CREATE TABLE `ext_act_process_form` (
  `id` varchar(32) NOT NULL,
  `relation_code` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '唯一编码',
  `biz_name` varchar(30) DEFAULT NULL COMMENT '业务名称描述',
  `process_id` varchar(50) NOT NULL COMMENT '流程ID',
  `form_table_name` varchar(100) DEFAULT NULL COMMENT 'Online表名、自定义表单CODE、表名',
  `form_type` varchar(50) DEFAULT NULL COMMENT '表单类型：1Online表单,2自定义表单,3自定义开发',
  `title_exp` varchar(150) DEFAULT NULL COMMENT '标题表达式',
  `form_deal_style` varchar(100) DEFAULT NULL COMMENT '流程办理风格',
  `flow_status_col` varchar(50) DEFAULT NULL COMMENT '流程状态列名',
  `trigger_action` varchar(50) DEFAULT NULL COMMENT '触发动作(add/update/delete, 多个动作|拼接)',
  `low_app_id` varchar(50) DEFAULT NULL COMMENT '应用ID',
  `tenant_id` int DEFAULT NULL COMMENT '租户ID',
  `start_signal_name` varchar(500) DEFAULT NULL COMMENT '信号名称',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE KEY `uk_eapf_relation_code` (`relation_code`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3 COMMENT='业务基础表';

-- ----------------------------
-- Records of ext_act_process_form
-- ----------------------------
BEGIN;
COMMIT;

-- ----------------------------
-- Table structure for ext_act_process_node
-- ----------------------------
DROP TABLE IF EXISTS `ext_act_process_node`;
CREATE TABLE `ext_act_process_node` (
  `id` varchar(32) NOT NULL,
  `form_id` varchar(32) DEFAULT NULL,
  `process_id` varchar(50) DEFAULT NULL COMMENT '流程ID',
  `process_node_code` varchar(50) DEFAULT NULL COMMENT '节点CODE',
  `process_node_name` varchar(50) DEFAULT NULL COMMENT '节点名称',
  `model_and_view` varchar(500) DEFAULT NULL,
  `model_and_view_mobile` varchar(500) DEFAULT NULL COMMENT '外部表单跳转方法(移动端)',
  `node_timeout` int DEFAULT NULL COMMENT '节点任务超时设置（单位时）',
  `node_bpm_status` varchar(32) DEFAULT NULL COMMENT '流程状态',
  `form_edit_status` varchar(3) DEFAULT '0' COMMENT '表单是否可编辑1是0否',
  `cc_status` varchar(3) DEFAULT '1' COMMENT '是否可以选择抄送人1是0否',
  `selnext_user_status` varchar(3) DEFAULT '1' COMMENT '是否可以选择下一步操作人1是0否',
  `msg_status` varchar(3) DEFAULT NULL COMMENT '是否支持消息通知1是0否',
  `node_config_json` longtext COMMENT '节点配置(存邮件\\系统消息\\钉钉推送的配置)',
  `transfer_status` varchar(3) DEFAULT NULL COMMENT '是否允许转办1是0否',
  `add_sign_status` varchar(3) DEFAULT NULL COMMENT '是否允许加签1是0否',
  `reject_status` varchar(3) DEFAULT NULL COMMENT '是否允许驳回1是0否',
  `allow_counter_sign_add_user` varchar(1) DEFAULT NULL COMMENT '是否允许会签节点加人0否、1允许',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3 COMMENT='流程节点表';

-- ----------------------------
-- Records of ext_act_process_node
-- ----------------------------
BEGIN;
COMMIT;

-- ----------------------------
-- Table structure for ext_act_process_node_auth
-- ----------------------------
DROP TABLE IF EXISTS `ext_act_process_node_auth`;
CREATE TABLE `ext_act_process_node_auth` (
  `id` varchar(32) NOT NULL,
  `process_id` varchar(50) DEFAULT NULL COMMENT '流程ID',
  `process_node_code` varchar(50) DEFAULT NULL COMMENT '节点编码',
  `rule_code` varchar(255) DEFAULT NULL COMMENT '规则编码',
  `rule_name` varchar(255) DEFAULT NULL COMMENT '规则名称',
  `rule_type` varchar(255) DEFAULT NULL COMMENT '策略1显示2禁用',
  `status` varchar(2) DEFAULT NULL COMMENT '状态(0无效1有效)',
  `required` tinyint(1) DEFAULT '0' COMMENT '是否必填 1必填 0否',
  `create_by` varchar(50) DEFAULT NULL COMMENT '创建人登录名称',
  `create_time` datetime DEFAULT NULL COMMENT '创建日期',
  `update_by` varchar(50) DEFAULT NULL COMMENT '更新人登录名称',
  `update_time` datetime DEFAULT NULL COMMENT '更新日期',
  `form_type` varchar(50) NOT NULL DEFAULT '3' COMMENT '表单类型：1Online表单,2自定义表单,3自定义开发',
  `form_biz_code` varchar(200) DEFAULT NULL COMMENT '表单设计编码',
  `desform_com_key` varchar(100) DEFAULT NULL COMMENT '组件id json中的key',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE KEY `uk_eapna_pid_nodecode_rulecode` (`process_id`,`process_node_code`,`rule_code`,`rule_type`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3 COMMENT='流程节点权限表';

-- ----------------------------
-- Records of ext_act_process_node_auth
-- ----------------------------
BEGIN;
COMMIT;

-- ----------------------------
-- Table structure for ext_act_process_node_deploy
-- ----------------------------
DROP TABLE IF EXISTS `ext_act_process_node_deploy`;
CREATE TABLE `ext_act_process_node_deploy` (
  `id` varchar(32) NOT NULL,
  `form_id` varchar(32) DEFAULT NULL,
  `process_id` varchar(32) DEFAULT NULL COMMENT '流程ID',
  `process_node_code` varchar(50) DEFAULT NULL COMMENT '节点CODE',
  `process_node_name` varchar(50) DEFAULT NULL COMMENT '节点名称',
  `model_and_view` varchar(500) DEFAULT NULL,
  `model_and_view_mobile` varchar(500) DEFAULT NULL COMMENT '外部表单跳转方法(移动端)',
  `node_timeout` int DEFAULT NULL COMMENT '节点任务超时设置（单位时）',
  `node_bpm_status` varchar(32) DEFAULT NULL COMMENT '流程状态',
  `form_edit_status` varchar(3) DEFAULT '1' COMMENT '表单是否可编辑1是0否',
  `cc_status` varchar(3) DEFAULT '1' COMMENT '是否可以选择抄送人1是0否',
  `selnext_user_status` varchar(3) DEFAULT '1' COMMENT '是否可以选择下一步操作人1是0否',
  `msg_status` varchar(3) DEFAULT '0' COMMENT '是否支持消息通知1是0否',
  `deployment_id` varchar(64) DEFAULT NULL COMMENT '部署id',
  `node_config_json` longtext COMMENT '节点配置(存邮件系统消息钉钉推送的配置)',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `idx_eapnd_code_depid` (`process_node_code`,`deployment_id`) USING BTREE,
  KEY `idx_eapnd_deployment_id` (`deployment_id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3 COMMENT='流程节点部署表';

-- ----------------------------
-- Records of ext_act_process_node_deploy
-- ----------------------------
BEGIN;
COMMIT;

-- ----------------------------
-- Table structure for ext_act_task_cc
-- ----------------------------
DROP TABLE IF EXISTS `ext_act_task_cc`;
CREATE TABLE `ext_act_task_cc` (
  `id` varchar(32) NOT NULL COMMENT '序号',
  `proc_def_id` varchar(64) DEFAULT NULL COMMENT '流程定义ID',
  `task_def_key` varchar(255) DEFAULT NULL COMMENT '节点定义ID',
  `proc_inst_id` varchar(64) DEFAULT NULL COMMENT '流程实例ID',
  `execution_id` varchar(64) DEFAULT NULL COMMENT '执行实例ID',
  `task_id` varchar(64) DEFAULT NULL COMMENT '任务ID',
  `task_name` varchar(255) DEFAULT NULL COMMENT '名称',
