  `link_type` varchar(1) DEFAULT NULL COMMENT '链接方式(0 网络报表 1 网络连接 2 图表联动)',
  `api_url` varchar(1000) DEFAULT NULL COMMENT '外网api',
  `link_chart_id` varchar(50) DEFAULT NULL COMMENT '联动图表的ID',
  `expression` varchar(255) DEFAULT NULL COMMENT '表达式',
  `requirement` varchar(255) DEFAULT NULL COMMENT '条件',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `uniq_link_reportid` (`report_id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='超链接配置表';

-- ----------------------------
-- Records of jimu_report_link
-- ----------------------------
BEGIN;
COMMIT;

-- ----------------------------
-- Table structure for jimu_report_map
-- ----------------------------
DROP TABLE IF EXISTS `jimu_report_map`;
CREATE TABLE `jimu_report_map` (
  `id` varchar(64) NOT NULL COMMENT '主键',
  `label` varchar(125) DEFAULT NULL COMMENT '地图名称',
  `name` varchar(125) DEFAULT NULL COMMENT '地图编码',
  `data` longtext COMMENT '地图数据',
  `create_by` varchar(32) DEFAULT NULL COMMENT '创建人',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(32) DEFAULT NULL COMMENT '修改人',
  `update_time` datetime DEFAULT NULL COMMENT '修改时间',
  `del_flag` varchar(1) DEFAULT NULL COMMENT '0表示未删除,1表示删除',
  `sys_org_code` varchar(64) DEFAULT NULL COMMENT '所属部门',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE KEY `uniq_jmreport_map_name` (`name`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3 COMMENT='地图配置表';

-- ----------------------------
-- Records of jimu_report_map
-- ----------------------------
BEGIN;
COMMIT;

-- ----------------------------
-- Table structure for jimu_report_share
-- ----------------------------
DROP TABLE IF EXISTS `jimu_report_share`;
CREATE TABLE `jimu_report_share` (
  `id` varchar(32) NOT NULL COMMENT '主键',
  `report_id` varchar(32) DEFAULT NULL COMMENT '在线excel设计器id',
  `preview_url` varchar(1000) DEFAULT NULL COMMENT '预览地址',
  `preview_lock` varchar(4) DEFAULT NULL COMMENT '密码锁',
  `last_update_time` datetime DEFAULT NULL COMMENT '最后更新时间',
  `term_of_validity` varchar(1) DEFAULT NULL COMMENT '有效期(0:永久有效，1:1天，2:7天)',
  `status` varchar(1) DEFAULT NULL COMMENT '是否过期(0未过期，1已过期)',
  `preview_lock_status` varchar(1) DEFAULT NULL COMMENT '密码锁状态(0不存在密码锁，1存在密码锁)',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE KEY `uniq_jrs_report_id` (`report_id`) USING BTREE COMMENT '报表id唯一索引'
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='积木报表预览权限表';

-- ----------------------------
-- Records of jimu_report_share
-- ----------------------------
BEGIN;
COMMIT;

-- ----------------------------
-- Table structure for low_app
-- ----------------------------
DROP TABLE IF EXISTS `low_app`;
CREATE TABLE `low_app` (
  `id` varchar(50) NOT NULL COMMENT 'ID',
  `app_name` varchar(100) DEFAULT NULL COMMENT '应用名称',
  `app_cover_img` varchar(200) DEFAULT NULL COMMENT '应用封面，填图片地址',
  `app_label` varchar(20) DEFAULT NULL COMMENT '应用标签（用于分类应用）',
  `icon_type` varchar(50) DEFAULT NULL COMMENT '图标type（ant-design图标）',
  `icon_back_color` varchar(20) DEFAULT NULL COMMENT '图标背景颜色（颜色固定，只存序号）',
  `order_num` int DEFAULT NULL COMMENT '排序位置',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `create_by` varchar(32) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '创建人',
  `update_time` datetime DEFAULT NULL COMMENT '修改时间',
  `update_by` varchar(32) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '修改人',
  `tenant_id` int DEFAULT '0' COMMENT '租户ID',
  `app_note` text COMMENT '应用说明',
  `star_status` int DEFAULT NULL COMMENT '标星状态 1是 0否',
  `star_order_num` int DEFAULT NULL COMMENT '标星排序',
  `owner_id` varchar(32) DEFAULT NULL COMMENT '拥有者ID',
  `maint_status` int DEFAULT NULL COMMENT '维护状态 1是 0否',
  `maint_note` varchar(500) DEFAULT NULL COMMENT '维护说明',
  `open_status` int DEFAULT NULL COMMENT '应用开启状态 1是 0否',
  `del_flag` int DEFAULT NULL COMMENT '应用删除状态 1是 0否',
  `delete_by` varchar(50) DEFAULT NULL COMMENT '删除人',
  `delete_time` datetime DEFAULT NULL COMMENT '删除时间',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `normal_low_app_app_name` (`app_name`) USING BTREE,
  KEY `normal_low_app_app_label` (`app_label`) USING BTREE,
  KEY `idx_lowapp_tenant_id` (`tenant_id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

-- ----------------------------
-- Records of low_app
-- ----------------------------
BEGIN;
COMMIT;

-- ----------------------------
-- Table structure for low_app_auth_form
-- ----------------------------
DROP TABLE IF EXISTS `low_app_auth_form`;
CREATE TABLE `low_app_auth_form` (
  `id` varchar(36) NOT NULL,
  `create_by` varchar(50) DEFAULT NULL COMMENT '创建人',
  `create_time` datetime DEFAULT NULL COMMENT '创建日期',
  `update_by` varchar(50) DEFAULT NULL COMMENT '更新人',
  `update_time` datetime DEFAULT NULL COMMENT '更新日期',
  `app_role_id` varchar(50) DEFAULT NULL COMMENT '权限角色ID',
  `design_form_code` varchar(100) DEFAULT NULL COMMENT '表单编码/仪表盘ID',
  `view_id` varchar(50) DEFAULT NULL COMMENT '视图ID',
  `auth_create` int DEFAULT NULL COMMENT '新增权限-作用于表单，1是0否',
  `auth_update` int DEFAULT NULL COMMENT '修改权限-作用于视图，1是0否',
  `auth_read` int DEFAULT NULL COMMENT '查看权限-作用于视图，1是0否',
  `auth_delete` int DEFAULT NULL COMMENT '删除权限-作用于视图，1是0否',
  `auth_type` varchar(50) DEFAULT NULL COMMENT '授权类型，仪表盘drag/设计器表单desform/设计器视图view',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `idx_laaf_app_role_id` (`app_role_id`) USING BTREE,
  KEY `idx_laaf_design_form_code` (`design_form_code`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

