-- Table structure for low_app_auth_form_field
-- ----------------------------
DROP TABLE IF EXISTS `low_app_auth_form_field`;
CREATE TABLE `low_app_auth_form_field` (
  `id` varchar(36) NOT NULL,
  `create_by` varchar(50) DEFAULT NULL COMMENT '创建人',
  `create_time` datetime DEFAULT NULL COMMENT '创建日期',
  `update_by` varchar(50) DEFAULT NULL COMMENT '更新人',
  `update_time` datetime DEFAULT NULL COMMENT '更新日期',
  `app_role_id` varchar(50) DEFAULT NULL COMMENT '权限角色ID',
  `design_form_code` varchar(100) DEFAULT NULL COMMENT '表单编码',
  `field_key` varchar(100) DEFAULT NULL COMMENT '表单字段key',
  `auth_create` int DEFAULT NULL COMMENT '字段新增权限，1是0否',
  `auth_update` int DEFAULT NULL COMMENT '字段编辑权限，1是0否',
  `auth_read` int DEFAULT NULL COMMENT '字段查看权限，1是0否',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `idx_laaff_app_role_id` (`app_role_id`) USING BTREE,
  KEY `idx_laaff_design_form_code` (`design_form_code`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

