-- Table structure for low_app_auth_form_operation
-- ----------------------------
DROP TABLE IF EXISTS `low_app_auth_form_operation`;
CREATE TABLE `low_app_auth_form_operation` (
  `id` varchar(36) NOT NULL,
  `create_by` varchar(50) DEFAULT NULL COMMENT '创建人',
  `create_time` datetime DEFAULT NULL COMMENT '创建日期',
  `update_by` varchar(50) DEFAULT NULL COMMENT '更新人',
  `update_time` datetime DEFAULT NULL COMMENT '更新日期',
  `app_role_id` varchar(50) DEFAULT NULL COMMENT '权限角色ID',
  `design_form_code` varchar(100) DEFAULT NULL COMMENT '表单编码',
  `op_key` varchar(32) DEFAULT NULL COMMENT '权限编码',
  `op_type` varchar(32) DEFAULT NULL COMMENT '工作表table/记录record/自定义按钮button',
  `op_status` int DEFAULT NULL COMMENT '是否授权，1是0否',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `idx_laafo_app_role_id` (`app_role_id`) USING BTREE,
  KEY `idx_laafo_design_form_code` (`design_form_code`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

