-- Table structure for low_app_auth_form_record
-- ----------------------------
DROP TABLE IF EXISTS `low_app_auth_form_record`;
CREATE TABLE `low_app_auth_form_record` (
  `id` varchar(36) NOT NULL,
  `create_by` varchar(50) DEFAULT NULL COMMENT '创建人',
  `create_time` datetime DEFAULT NULL COMMENT '创建日期',
  `update_by` varchar(50) DEFAULT NULL COMMENT '更新人',
  `update_time` datetime DEFAULT NULL COMMENT '更新日期',
  `app_role_id` varchar(50) DEFAULT NULL COMMENT '权限角色ID',
  `design_form_code` varchar(100) DEFAULT NULL COMMENT '表单编码',
  `scope_key` varchar(32) DEFAULT NULL COMMENT '记录范围授权key',
  `subordinate` int DEFAULT NULL COMMENT '是否包含下属加入的记录，1是0否',
  `scope_type` varchar(32) DEFAULT NULL COMMENT '查看/删除/修改',
  `auth_mode` varchar(50) DEFAULT NULL COMMENT '授权分发方式easy/super',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `idx_laafr_app_role_id` (`app_role_id`) USING BTREE,
  KEY `idx_laafr_design_form_code` (`design_form_code`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

