BEGIN;
COMMIT;

-- ----------------------------
-- Table structure for low_app_auth_role
-- ----------------------------
DROP TABLE IF EXISTS `low_app_auth_role`;
CREATE TABLE `low_app_auth_role` (
  `id` varchar(50) NOT NULL,
  `create_by` varchar(50) DEFAULT NULL COMMENT '创建人',
  `create_time` datetime DEFAULT NULL COMMENT '创建日期',
  `update_by` varchar(50) DEFAULT NULL COMMENT '更新人',
  `update_time` datetime DEFAULT NULL COMMENT '更新日期',
  `name` varchar(50) DEFAULT NULL COMMENT '角色名称',
  `description` varchar(1000) DEFAULT NULL COMMENT '角色描述',
  `auth_mode` varchar(32) DEFAULT NULL COMMENT '分发方式easy/super',
  `app_id` varchar(50) DEFAULT NULL COMMENT '应用ID',
  `tenant_id` int DEFAULT NULL COMMENT '租户',
  `code` varchar(50) DEFAULT NULL COMMENT '默认的三个角色有编码 admin/element/readonly',
  `order_num` int DEFAULT NULL COMMENT '排序',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `idx_laar_tenant_id` (`tenant_id`) USING BTREE,
  KEY `idx_laar_app_id` (`app_id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

