CREATE TABLE `low_app_auth_role_user` (
  `id` varchar(50) NOT NULL,
  `create_by` varchar(50) DEFAULT NULL COMMENT '创建人',
  `create_time` datetime DEFAULT NULL COMMENT '创建日期',
  `auth_role_id` varchar(50) DEFAULT NULL COMMENT '授权角色ID',
  `type` varchar(50) DEFAULT NULL COMMENT '类型：人员sys_user/部门sys_depart/组织角色sys_role/职位sys_position',
  `relation_id` varchar(32) DEFAULT NULL COMMENT '用户表/部门表ID,对应type，找不同的表',
  `app_id` varchar(50) DEFAULT NULL COMMENT 'appid',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `update_by` varchar(50) DEFAULT NULL COMMENT '更新人',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE KEY `uk_laaru_app_auth_role_user` (`app_id`,`relation_id`,`auth_role_id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

