-- ----------------------------
-- Table structure for low_app_menu
-- ----------------------------
DROP TABLE IF EXISTS `low_app_menu`;
CREATE TABLE `low_app_menu` (
  `id` varchar(50) NOT NULL COMMENT 'ID',
  `menu_name` varchar(100) DEFAULT NULL COMMENT '菜单名称',
  `menu_url` varchar(200) DEFAULT NULL COMMENT '菜单地址',
  `app_id` varchar(50) DEFAULT NULL COMMENT '应用ID',
  `type` varchar(50) DEFAULT NULL COMMENT '类型：group=菜单分组；cgform=online表单；desform=表单设计器；cgreport=Online报表；jimureport=积木报表；process=流程；graphreport=Online图表',
  `parent_id` varchar(50) DEFAULT NULL COMMENT '父ID',
  `icon_type` varchar(50) DEFAULT NULL COMMENT 'AntDesign的图标类型',
  `order_num` int DEFAULT NULL COMMENT '排序',
  `del_flag` tinyint(1) DEFAULT NULL COMMENT '删除状态(0-正常,1-已删除)',
  `desform_code` varchar(100) DEFAULT NULL COMMENT '当type=form时，存的对应的desformCode',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `create_by` varchar(32) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '创建人',
  `update_time` datetime DEFAULT NULL COMMENT '修改时间',
  `update_by` varchar(32) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '修改人',
  `hide_flag` tinyint(1) DEFAULT NULL COMMENT '隐藏状态(1-隐藏， 0-正常)',
  `menu_note` text COMMENT '工作表说明',
  `add_button_label` varchar(50) DEFAULT NULL COMMENT '添加按钮的文字',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `normal_low_app_menu_app_id` (`app_id`) USING BTREE,
  KEY `normal_low_app_menu_parent_id` (`parent_id`) USING BTREE,
  KEY `normal_low_app_menu_del_flag` (`del_flag`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

-- ----------------------------
-- Records of low_app_menu
-- ----------------------------
BEGIN;
COMMIT;

-- ----------------------------
-- Table structure for low_app_template
-- ----------------------------
DROP TABLE IF EXISTS `low_app_template`;
CREATE TABLE `low_app_template` (
  `id` varchar(32) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL COMMENT '主键id',
  `title` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '标题',
  `sub_title` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '副标题',
  `category` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '类别',
  `industry` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '行业',
  `tag` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '模版标签',
  `cover_url` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '封面图',
  `introduce` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT '模版详情介绍',
  `rotation_pics` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '模版详情轮播图',
  `video_url` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '0' COMMENT '模版视频简介地址',
  `iz_publish` tinyint(1) DEFAULT NULL COMMENT '针对审核完的模版，客户自主控制上架/下架（0-否，1-是）',
  `publish_time` datetime DEFAULT NULL COMMENT '发布时间',
  `reject_cause` varchar(125) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '审核未通过原因',
  `status` tinyint(1) DEFAULT NULL COMMENT '状态(0-草稿，1审核中, 2-审核通过,-1 未通过)',
  `bind_low_app_id` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '绑定应用id',
  `download_num` int DEFAULT '0' COMMENT '下载次数',
  `like_num` int DEFAULT '0' COMMENT '点赞次数',
  `rate_num` int DEFAULT '0' COMMENT '评分次数',
  `rate` int DEFAULT '0' COMMENT '综合评分',
  `free_status` tinyint(1) DEFAULT '0' COMMENT '状态(0-免费，1收费)',
  `price` decimal(10,2) DEFAULT NULL COMMENT '定价',
  `del_flag` tinyint(1) DEFAULT '0' COMMENT '删除状态(0-正常,1-已删除)',
  `tenant_id` int DEFAULT NULL COMMENT '租户id',
  `create_by` varchar(32) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '创建人',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(32) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '更新人',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `normal_low_app_template_title` (`title`) USING BTREE,
  KEY `normal_low_app_template_status` (`status`) USING BTREE,
  KEY `normal_low_app_template_tag` (`tag`) USING BTREE,
  KEY `normal_low_app_template_industry` (`industry`) USING BTREE,
  KEY `normal_low_app_template_category` (`category`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='应用模版表';

-- ----------------------------
-- Records of low_app_template
-- ----------------------------
BEGIN;
COMMIT;

-- ----------------------------
-- Table structure for low_app_template_comment
-- ----------------------------
DROP TABLE IF EXISTS `low_app_template_comment`;
CREATE TABLE `low_app_template_comment` (
  `id` varchar(32) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL COMMENT '主键id',
  `template_id` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '绑定模版id',
  `rate` int DEFAULT '0' COMMENT '评分',
  `iz_like` tinyint(1) DEFAULT NULL COMMENT '点赞（0否 1是）',
  `comment_content` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '评论',
  `realname` varchar(100) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '评论人姓名',
  `avatar` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '账户头像',
  `del_flag` tinyint(1) DEFAULT '0' COMMENT '删除状态(0-正常,1-已删除)',
  `create_by` varchar(32) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '创建人',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(32) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '更新人',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `idx_template_id` (`template_id`) USING BTREE,
  KEY `idx_create_by` (`update_by`) USING BTREE,
  KEY `idx_iz_like` (`iz_like`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='应用模版评论表';

