-- Table structure for sys_role_design
-- ----------------------------
DROP TABLE IF EXISTS `sys_role_design`;
CREATE TABLE `sys_role_design` (
  `id` varchar(32) NOT NULL COMMENT '主键',
  `role_id` varchar(32) DEFAULT NULL COMMENT '角色id',
  `design_id` varchar(32) DEFAULT NULL COMMENT '表单设计器id',
  PRIMARY KEY (`id`) USING BTREE
