-- Table structure for sys_table_white_list
-- ----------------------------
DROP TABLE IF EXISTS `sys_table_white_list`;
CREATE TABLE `sys_table_white_list` (
  `id` varchar(32) NOT NULL COMMENT '主键id',
  `table_name` varchar(100) DEFAULT NULL COMMENT '允许的表名',
  `field_name` varchar(200) DEFAULT NULL COMMENT '允许的字段名，多个用逗号分割',
  `status` varchar(10) DEFAULT '1' COMMENT '状态，1=启用，0=禁用',
  `create_by` varchar(32) DEFAULT NULL COMMENT '创建人',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(32) DEFAULT NULL COMMENT '更新人',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE KEY `uniq_sys_table_white_list_table_name` (`table_name`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='系统表白名单';

