-- Records of sys_third_account
-- ----------------------------
BEGIN;
COMMIT;

-- ----------------------------
-- Table structure for sys_third_app_config
-- ----------------------------
DROP TABLE IF EXISTS `sys_third_app_config`;
CREATE TABLE `sys_third_app_config` (
  `id` varchar(32) NOT NULL,
  `tenant_id` int NOT NULL DEFAULT '0' COMMENT '租户id',
  `agent_id` varchar(20) DEFAULT NULL COMMENT '钉钉/企业微信应用id',
  `client_id` varchar(50) DEFAULT NULL COMMENT '钉钉/企业微信 应用id',
  `client_secret` varchar(100) DEFAULT NULL COMMENT '钉钉/企业微信应用id对应的秘钥',
  `third_type` varchar(20) DEFAULT NULL COMMENT '第三方类别(dingtalk 钉钉 wechat_enterprise 企业微信)',
  `agent_app_secret` varchar(100) DEFAULT NULL COMMENT '自建应用Secret',
  `status` int DEFAULT '1' COMMENT '是否启用(0-否,1-是)',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `idx_stac_tenant_id` (`tenant_id`) USING BTREE,
  KEY `idx_stac_third_type` (`third_type`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='租户第三方配置表';

