-- ----------------------------
-- Procedure structure for completeAppData1
-- ----------------------------
DROP PROCEDURE IF EXISTS `completeAppData1`;
delimiter ;;
CREATE PROCEDURE `completeAppData1`()
begin
-- 创建人
DECLARE tmp_create_by VARCHAR(500);
-- appId
DECLARE tmp_app_id VARCHAR(500);
-- tenant
DECLARE tmp_tenant_id VARCHAR(500);
-- authRoleId
DECLARE tmp_ar_id VARCHAR(500);
-- user_id
DECLARE tmp_user_id VARCHAR(500);
-- 数量
DECLARE admin_count int DEFAULT 0;
-- 数量2
DECLARE auth_count int DEFAULT 0;

DECLARE b int default 0;
DECLARE list CURSOR for select id,create_by,tenant_id from low_app;
DECLARE CONTINUE HANDLER FOR NOT FOUND SET b = 1;

OPEN list;
 while b<>1 do
 FETCH list into tmp_app_id, tmp_create_by, tmp_tenant_id;
 -- 修改拥有者
 select id into tmp_user_id from sys_user where username = tmp_create_by;
 update low_app set owner_id = tmp_user_id;
 -- 添加默认角色admin
 select count(1) into admin_count from low_app_auth_role where app_id = tmp_app_id and code = 'admin';
if (admin_count>0) then
    select id into tmp_ar_id from low_app_auth_role where app_id = tmp_app_id and code = 'admin';
else
		SET tmp_ar_id = REPLACE (uuid(), '-', '');
end if;

-- 添加角色用户关系
 select count(1) into auth_count from low_app_auth_role_user where app_id = tmp_app_id and auth_role_id = tmp_ar_id and relation_id = tmp_user_id;
 if (auth_count=0) then

end if;

 end while;
close list;
end
;;
delimiter ;

SET FOREIGN_KEY_CHECKS = 1;
